package com.portfolio.controller;
import com.portfolio.model.Experience; import com.portfolio.repository.ExperienceRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/experience") public class ExperienceController { private final ExperienceRepository repo; public ExperienceController(ExperienceRepository r){repo=r;} @GetMapping public List<Experience> all(){return repo.findAllByOrderByDisplayOrderAsc();} @GetMapping("/{id}") public ResponseEntity<Experience> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public Experience create(@RequestBody Experience x){return repo.save(x);} @PutMapping("/{id}") public ResponseEntity<Experience> update(@PathVariable Long id,@RequestBody Experience p){return repo.findById(id).map(x->{
x.setCompany(p.getCompany());x.setRole(p.getRole());x.setLocation(p.getLocation());x.setStartDate(p.getStartDate());x.setEndDate(p.getEndDate());x.setDescription(p.getDescription());x.setDisplayOrder(p.getDisplayOrder());return ResponseEntity.ok(repo.save(x));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }